                  where p.fondo_id = f.id and p.slug = v.slug);

-- verifica: devono uscire 118 persone e 118 slug distinti
select (select count(*) from public.memoria_persona) as persone,
       (select count(distinct slug) from public.memoria_persona) as slug_distinti,
       (select count(*) from public.memoria_persona where prigioniero_guerra) as prigionieri,
       (select count(*) from public.memoria_persona where regione_nascita is not null) as con_provenienza;

